CREATE TABLE el_course_prerequisites(org_id TEXT NOT NULL,course_id TEXT NOT NULL,prerequisite_id TEXT NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,CHECK(course_id<>prerequisite_id),PRIMARY KEY(org_id,course_id,prerequisite_id),FOREIGN KEY(org_id,course_id) REFERENCES el_courses(org_id,id),FOREIGN KEY(org_id,prerequisite_id) REFERENCES el_courses(org_id,id),FOREIGN KEY(org_id,created_by) REFERENCES el_memberships(org_id,user_id));
CREATE INDEX el_course_prerequisites_reverse ON el_course_prerequisites(org_id,prerequisite_id,course_id);
CREATE TRIGGER el_course_prerequisite_guard BEFORE INSERT ON el_course_prerequisites BEGIN
 SELECT CASE WHEN (SELECT count(*) FROM el_course_prerequisites WHERE org_id=NEW.org_id AND course_id=NEW.course_id)>=20 THEN RAISE(ABORT,'Course prerequisite limit reached') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_courses c JOIN el_courses p ON p.org_id=c.org_id AND p.id=NEW.prerequisite_id WHERE c.org_id=NEW.org_id AND c.id=NEW.course_id AND c.status='active' AND p.status='active') THEN RAISE(ABORT,'Course prerequisite must be active') END;
 SELECT CASE WHEN EXISTS(WITH RECURSIVE chain(id) AS(SELECT prerequisite_id FROM el_course_prerequisites WHERE org_id=NEW.org_id AND course_id=NEW.prerequisite_id UNION SELECT p.prerequisite_id FROM el_course_prerequisites p JOIN chain c ON c.id=p.course_id WHERE p.org_id=NEW.org_id) SELECT 1 FROM chain WHERE id=NEW.course_id) THEN RAISE(ABORT,'Course prerequisite cycle') END;
END;
CREATE TRIGGER el_course_prerequisite_identity BEFORE UPDATE ON el_course_prerequisites BEGIN SELECT RAISE(ABORT,'Course prerequisite identity is immutable'); END;
CREATE TRIGGER el_enrollment_prerequisite_insert BEFORE INSERT ON el_enrollments WHEN NEW.status IN ('active','waiting') BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM el_course_prerequisites p JOIN el_groups target ON target.course_id=p.course_id AND target.org_id=p.org_id WHERE target.id=NEW.group_id AND p.org_id=NEW.org_id AND NOT EXISTS(SELECT 1 FROM el_enrollments completed JOIN el_groups prior ON prior.id=completed.group_id AND prior.org_id=completed.org_id WHERE completed.org_id=NEW.org_id AND completed.student_id=NEW.student_id AND completed.status='completed' AND prior.course_id=p.prerequisite_id)) THEN RAISE(ABORT,'Course prerequisite completion required') END;
END;
CREATE TRIGGER el_enrollment_prerequisite_update BEFORE UPDATE OF status,group_id,student_id ON el_enrollments WHEN NEW.status IN ('active','waiting') AND (NEW.status<>OLD.status OR NEW.group_id<>OLD.group_id OR NEW.student_id<>OLD.student_id) BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM el_course_prerequisites p JOIN el_groups target ON target.course_id=p.course_id AND target.org_id=p.org_id WHERE target.id=NEW.group_id AND p.org_id=NEW.org_id AND NOT EXISTS(SELECT 1 FROM el_enrollments completed JOIN el_groups prior ON prior.id=completed.group_id AND prior.org_id=completed.org_id WHERE completed.org_id=NEW.org_id AND completed.student_id=NEW.student_id AND completed.status='completed' AND prior.course_id=p.prerequisite_id)) THEN RAISE(ABORT,'Course prerequisite completion required') END;
END;
